from binkeep import journal
from binkeep.bins import normalize
from binkeep.errors import DataError, Refused


def _broken(message: str) -> DataError:
    return DataError("journal", message)


def is_operation(e: dict) -> bool:
    return e["op"] in journal.OPS


def _effects(e: dict) -> list[tuple[str, int]]:
    """The (bin, before) pairs of a format 2 line, with a bin that is as recorded."""
    raw = e.get("effects")
    if not isinstance(raw, list):
        raise _broken(f"#{e['seq']}: no effects")
    out = []
    for x in raw:
        if (not isinstance(x, dict) or not isinstance(x.get("bin"), str)
                or not isinstance(x.get("before"), int) or isinstance(x.get("before"), bool)):
            raise _broken(f"#{e['seq']}: bad effect")
        out.append((normalize(x["bin"]), x["before"]))
    return out


class Stacks:
    """The *done* and *undone* stacks, read from the journal (undo.md, section 2)."""

    def __init__(self):
        self.done: list[dict] = []
        self.undone: list[tuple[dict, dict]] = []  # (operation, the undo line that undid it)
        self.dropped: list[dict] = []

    def feed(self, e: dict) -> None:
        op = e["op"]
        if op in journal.OPS:
            self.dropped.extend(o for o, _ in self.undone)
            self.undone.clear()
            self.done.append(e)
        elif op == "undo":
            if not self.done or e.get("target") != self.done[-1]["seq"] or isinstance(e.get("target"), bool):
                raise _broken(f"#{e['seq']}: undo does not match the operations done")
            self.undone.append((self.done.pop(), e))
        elif op == "redo":
            if not self.undone or e.get("target") != self.undone[-1][0]["seq"] or isinstance(e.get("target"), bool):
                raise _broken(f"#{e['seq']}: redo does not match the operations undone")
            self.done.append(self.undone.pop()[0])

    @classmethod
    def read(cls, entries: list[dict]) -> "Stacks":
        s = cls()
        for e in entries:
            s.feed(e)
        return s


def _forward_changes(ctx, e: dict) -> list[tuple[str, int]]:
    """The (bin, change in units) of a format 1 line, in the order they were made."""
    try:
        op = e["op"]
        if op == "receive":
            qty = e["qty"]
            if e.get("uom") == "pk":
                item = ctx.items.get(e["sku"])
                if item is None:
                    raise Refused("unknown-sku", f"no item {e['sku']}")
                qty *= item.pack_size
            return [(normalize(e["bin"]), qty)]
        if op == "issue":
            return [(normalize(b), -q) for b, q in e["picks"]]
        if op == "move":
            return [(normalize(e["from"]), -e["qty"]), (normalize(e["to"]), e["qty"])]
    except (KeyError, TypeError, ValueError, AttributeError):
        raise _broken(f"#{e['seq']}: cannot read the line") from None
    raise _broken(f"#{e['seq']}: cannot read the line")


def _undo_plan(ctx, store, op: dict) -> list[tuple[str, int]]:
    """The (bin, new quantity) settings that reverse an operation, in order, on a copy of the store."""
    sku = op.get("sku")
    if op.get("v") == 2:
        return [(code, before) for code, before in reversed(_effects(op))]
    plan = []
    work = store.copy()
    for code, delta in reversed(_forward_changes(ctx, op)):
        if code not in ctx.bins:
            raise Refused("unknown-bin", f"no bin {code}")
        new = work.qty(sku, code) - delta
        work.restore(sku, code, new)
        plan.append((code, new))
    return plan


def _apply(ctx, store, sku: str, plan: list[tuple[str, int]]) -> list[dict]:
    for code, _ in plan:
        if code not in ctx.bins:
            raise Refused("unknown-bin", f"no bin {code}")
    effects = []
    for code, qty in plan:
        before = store.qty(sku, code)
        store.restore(sku, code, qty)
        effects.append({"bin": code, "before": before, "after": qty})
    return effects


def run(ctx, name: str, steps: int):
    """Carries out `steps` undo or redo steps; returns the store and the new journal lines."""
    store = ctx.store.copy()
    stacks = Stacks.read(ctx.entries)
    seq = journal.next_seq(ctx.entries)
    new = []
    for _ in range(steps):
        if name == "undo":
            if not stacks.done:
                raise Refused("nothing-to-undo", "nothing to undo")
            op = stacks.done[-1]
            if op["op"] == "fix":
                raise Refused("barrier", f"#{op['seq']} is a fix")
            if op["op"] == "count" and op.get("v") != 2:
                raise Refused("irreversible", f"#{op['seq']} is a count without the earlier quantity")
            plan = _undo_plan(ctx, store, op)
        else:
            if not stacks.undone:
                raise Refused("nothing-to-redo", "nothing to redo")
            op, undo_line = stacks.undone[-1]
            plan = [(code, before) for code, before in reversed(_effects(undo_line))]
        sku = op.get("sku", "")
        effects = _apply(ctx, store, sku, plan)
        line = journal.entry(seq, name, ctx.by, sku, target=op["seq"], effects=effects)
        stacks.feed(line)
        new.append((line, op["op"]))
        seq += 1
    return store, new


def history(entries: list[dict], limit: int) -> list[str]:
    stacks = Stacks.read(entries)
    done = {id(e) for e in stacks.done}
    undone = {id(o) for o, _ in stacks.undone}
    dropped = {id(o) for o in stacks.dropped}
    ops = [e for e in entries if is_operation(e)]
    lines = []
    for e in reversed(ops[-limit:]):
        if id(e) in dropped:
            status = "dropped"
        elif id(e) in undone:
            status = "undone"
        elif e["op"] == "fix":
            status = "barrier"
        else:
            status = "done"
        lines.append(f"{e['seq']:>5}  {e['op']:<7}  {e.get('sku', ''):<10}  {status}")
    return lines
"}

